package br.com.poolcontrol.financeiro.api;
import br.com.poolcontrol.financeiro.api.dto.ReconciliationRequest; import br.com.poolcontrol.financeiro.domain.*; import br.com.poolcontrol.financeiro.repository.*; import br.com.poolcontrol.financeiro.service.ReconciliationService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/financeiro/conciliacao") @RequiredArgsConstructor public class ReconciliationController { private final ReconciliationService service; private final BankStatementEntryRepository extratos; private final ReconciliationRepository conciliacoes;
 @GetMapping("/extratos") List<BankStatementEntry> extratos(){return extratos.findAll();} @PostMapping("/extratos") BankStatementEntry extrato(@RequestBody BankStatementEntry e){return extratos.save(e);} @PostMapping public Reconciliation conciliar(@Valid @RequestBody ReconciliationRequest r){return service.reconcile(r);} @GetMapping List<Reconciliation> listar(){return conciliacoes.findAll();} }
